INSERT OR IGNORE INTO "Game" ("id", "name", "status", "currentPhase", "activeVoteRound") VALUES ('cmpg2bw0w0000ej7dyc1todr9', 'Dead in the Water', 'SETUP', 0, NULL);

INSERT OR IGNORE INTO "Character" ("id", "gameId", "personaName", "realName", "role", "loginCode", "isGameMaster", "prop", "avatarColor", "sheet", "sortOrder") VALUES ('cmpg2bw160001ej7d0w0kzxk4', 'cmpg2bw0w0000ej7dyc1todr9', 'Hank Whitfield', 'Daniel', 'SINNER', 'HANK-01', 0, 'A bolo tie. Wear it.', '#a8741f', '[{"heading":"Who you are","body":"You are 56. Self-made commercial real estate. You grew up on a ranch; your father was a hard man who never gave you a dime. You have a mild temper that flashes when pushed, and a famous “no politics in this house” rule you defend at any provocation. You are the patriarch of the Whitfield family."},{"heading":"Your relationship to Richard","body":"Richard claims to be your 10th step half-brother. You''ve never been able to verify it. He''s been sending letters and bizarre gifts (an engraved lobster fork, a nautical chart of Gig Harbor) for a year. You agreed to host because Catherine wanted to “for the kids.” You don''t trust him and you don''t want his money."},{"heading":"Where you were Saturday night","body":"Bonfire from 9 PM. With Catherine on the patio between 11 and 12. You did NOT go to the dock."},{"heading":"Your secret","body":"At 8 PM in the gazebo, you and Richard had a private confrontation. He mocked your father, the ranch, your “self-made man” story. You shoved him into a stack of life jackets. He laughed. You walked out — and tore a small scrap of fabric from his green tweed jacket as you grabbed him. It''s folded inside the inner pocket of your coat in the entryway closet. Solomon watched the whole thing. You''ve told no one, not even Catherine, because it makes you look guilty."},{"heading":"What you don''t know","body":"Anything about the actual murder."},{"heading":"How to play it","body":"Mortified. You''ll be the loudest voice redirecting suspicion early — that''s your tell, but the family reads it as the temper. When Solomon screeches your gazebo words in Phase 2, you confess. Until then, deny."}]', 1);
INSERT OR IGNORE INTO "Character" ("id", "gameId", "personaName", "realName", "role", "loginCode", "isGameMaster", "prop", "avatarColor", "sheet", "sortOrder") VALUES ('cmpg2bw1d0002ej7dmbaee9xc', 'cmpg2bw0w0000ej7dyc1todr9', 'Catherine Whitfield', 'Nicole', 'SINNER', 'CATHERINE-02', 0, 'A silk scarf and a small notebook with a pen tucked in the spine.', '#7b6cae', '[{"heading":"Who you are","body":"You are 51. Loving, traditional, organized to a fault. You write — three published books on naturopathic medicine, herbal remedies, and the spiritual life. Your fourth book has been a secret."},{"heading":"Your relationship to Richard","body":"You found his letters charming at first and convinced Hank to host “for the kids.” You''ve been polite while quietly horrified by his theatrical cruelty."},{"heading":"Where you were Saturday night","body":"Tended the bonfire from 9 PM with brief trips inside. With Hank on the patio between 11 and 12."},{"heading":"Your secret","body":"You''ve been writing a tell-all family memoir for three years — Things My Mother Knew — with uncomfortable truths about every Whitfield. You sent a draft to a publisher in March. Friday you discovered Richard had obtained a copy and hinted at it at dinner. You panicked. At 9:30 PM Saturday you slipped into his guest room, took the draft, and burned every page in the bonfire."},{"heading":"What you''re hiding","body":"Nothing physical — you destroyed it. But a single charred page survived in the cooled fire pit ash."},{"heading":"How to play it","body":"Composed and loving. When the burned page is found in Phase 3, you confess. Frame it as protecting the family, not deceiving them."}]', 2);
INSERT OR IGNORE INTO "Character" ("id", "gameId", "personaName", "realName", "role", "loginCode", "isGameMaster", "prop", "avatarColor", "sheet", "sortOrder") VALUES ('cmpg2bw1j0003ej7dmi05bnk1', 'cmpg2bw0w0000ej7dyc1todr9', 'Vivienne “Vivi” Hawthorne', 'Sophia', 'ACCOMPLICE', 'VIVI-03', 0, 'Oversized black sunglasses (worn indoors as a Princess bit) and a single theater playbill.', '#b3122a', '[{"heading":"PRIVATE — read this alone","body":"This dossier contains the full plan. Do not let anyone see your screen."},{"heading":"Who you are","body":"You are 26. The Princess of the Whitfield family — only daughter, loved by everyone. You live in NYC. Your PR job is glamorous and unfulfilling. You love theater, food, singing, and being adored. You''re married to Sebastian."},{"heading":"Your relationship to Richard","body":"He doted on you — his “Princess.” For a year you''d written him secretly, asking for help to leave PR for theater. Saturday at 3 PM he pulled you aside and told you he was leaving everything to TURD — the Tortoise Urgent Rescue Division. He thought you''d be proud. You smiled. You said you were."},{"heading":"Your secret — you and Sebastian planned the murder together","body":"You walked back to the boathouse, found Sebastian, and told him about TURD. Within two hours you had a plan: he would do it, you would distract. You wrote “11:35 — go” on a note and gave it to him."},{"heading":"The night","body":"Just before 11:30 you slipped to the primary suite balcony with opera binoculars to make sure the dock was empty, then left them on the loveseat (you never came back for them). At 11:30 you launched a Broadway story you''d told before — the same one from last Christmas dinner — to fill exactly the time Sebastian needed. At 11:55 you went upstairs, balled up a sticky note that said “breathe. it''s done.” into the master bathroom trash, and came back at 12:02."},{"heading":"What you must lie about","body":"Whether Richard told you anything Saturday afternoon. Whether you saw anything from upstairs. Whether the “11:35 — go” note is your handwriting. The Christmas story."},{"heading":"How to play it / your break","body":"Charming, devastated, deflective. When Sebastian is unmasked in Phase 4, perform horror — admit nothing. In Phase 5, when the Christmas-story detail surfaces, you have ten seconds. Alexander will guide you. Your final confession is heavy: you are not asking forgiveness, you are explaining."}]', 3);
INSERT OR IGNORE INTO "Character" ("id", "gameId", "personaName", "realName", "role", "loginCode", "isGameMaster", "prop", "avatarColor", "sheet", "sortOrder") VALUES ('cmpg2bw1p0004ej7dqh2wxezc', 'cmpg2bw0w0000ej7dyc1todr9', 'Sebastian Hawthorne', 'Jaymon', 'KILLER', 'SEBASTIAN-04', 0, 'A clip-on tie and a navy blazer (the GM plants the envelope in the inside pocket before guests arrive).', '#1c4f7a', '[{"heading":"PRIVATE — read this alone","body":"This dossier identifies you as the killer. Do not let anyone see your screen."},{"heading":"Who you are","body":"You are 30. Smart, calculating, sarcastic, hard to read. MBA-bound — six figures in loans for an Ivy program in the fall. You want Wall Street. You enjoy strategy games and the taste of certainty."},{"heading":"Your relationship to Richard","body":"Outwardly cordial; privately you saw him as your route into real money. You and Vivi had been quietly drowning in NYC for a year — lease, MBA debt, a private-placement deposit — all sized to an inheritance you assumed was coming."},{"heading":"Where you were Saturday night","body":"“Stepped outside for some air,” 11:30–11:50 PM. A twenty-minute “smoke break.”"},{"heading":"Your secret — you killed him","body":"Saturday afternoon Vivi found you in the boathouse with the news about TURD. You planned together over two hours. At 11:35 you walked to the dock, took the loose cleat, swung once. Richard fell, struck the piling, went into the shallows. You threw the cleat in the lake, took the notarized envelope, and returned to the bonfire at 11:50."},{"heading":"What you''re hiding","body":"The notarized envelope is folded in the inside pocket of your navy blazer (on the back of your breakfast chair — you couldn''t move it). The “11:35 — go” note from Vivi is behind it. Your inheritance-vs-debt ledger is in a Monopoly box on the bottom floor. The dock-layout diagram you drew Friday is taped behind the orca mural."},{"heading":"What you must lie about","body":"The smoke break (you needed air). The envelope (you don''t know where it is). The diagram (never seen it). The ledger (just normal expense tracking)."},{"heading":"How to play it / your break","body":"Cool, dry, slightly above it. Click your pen when nervous — leave that tell in. Smug in Phase 2, uneasy in Phase 3. You break in Phase 4: when Cody''s photo lands, you can deny once, not twice. Confess short and clean. Do NOT implicate Vivi — you take the fall alone."}]', 4);
INSERT OR IGNORE INTO "Character" ("id", "gameId", "personaName", "realName", "role", "loginCode", "isGameMaster", "prop", "avatarColor", "sheet", "sortOrder") VALUES ('cmpg2bw1w0005ej7dcx8br2p4', 'cmpg2bw0w0000ej7dyc1todr9', 'Isabelle “Bella” Reyes', 'Samantha', 'SINNER', 'BELLA-05', 0, 'A lanyard with an “International Schools Initiative” badge and a clipboard with non-profit forms.', '#2f9e44', '[{"heading":"Who you are","body":"You are 25. You work for a humanitarian non-profit that builds schools and teaches English abroad. Sweet, tough, you fight for yourself. You''re engaged to Alexander — but here you''re a guest, not a Whitfield, still working on feeling like one of them."},{"heading":"Your relationship to Richard","body":"He met you at a Whitfield Christmas two years ago and promised your non-profit a $250,000 donation for a Cambodia school. He invited you up this weekend “to lock in the details.”"},{"heading":"Where you were Saturday night","body":"Helping in the kitchen with s''mores and mocktails 9–10:30. Bonfire 10:30 onward."},{"heading":"Your secret","body":"Saturday afternoon you discovered Richard had been stringing you along — the donation was never coming. You confronted him alone in the gazebo at 7 PM. He laughed at you. You walked out fuming."},{"heading":"What you''re hiding","body":"Nothing physical — just the fight. You''re terrified the gazebo confrontation makes you look like the murderer."},{"heading":"How to play it","body":"Tense, defensive, sharper than usual. When the torn guestbook page surfaces in Phase 3, you confess. Frame it as a fight, not a threat."}]', 5);
INSERT OR IGNORE INTO "Character" ("id", "gameId", "personaName", "realName", "role", "loginCode", "isGameMaster", "prop", "avatarColor", "sheet", "sortOrder") VALUES ('cmpg2bw210006ej7dwbfawlr3', 'cmpg2bw0w0000ej7dyc1todr9', 'Beau Whitfield', 'Colin', 'SINNER', 'BEAU-06', 0, 'A gym sweatband headband and a frosted plastic shaker bottle.', '#d9772b', '[{"heading":"Who you are","body":"You are 22. The middle child. Fiery red hair. Currently obsessed with the gym (the obsession changes every few months — last year, spoon rings; before that, your never-launched merch line “Beau Thats Hot”). Loud, funny, never a dull moment."},{"heading":"Your relationship to Richard","body":"Friday night you pitched him on investing in a “Beau Thats Hot” relaunch. He laughed in your face — said your idea had “the marketing instincts of a teen with a TikTok addiction.” You smiled and said “respect the honesty.”"},{"heading":"Where you were Saturday night","body":"Bonfire and patio. Tossing a football with Cody and Levi 9–10. You walked off briefly at 10 PM to “use the bathroom.”"},{"heading":"Your secret","body":"At 10 PM, instead of the bathroom, you stole Richard''s entire case of glass-bottle root beer from the kitchen and hid it under the second blue kayak on the patio. You drank one. You wanted to watch his face when he found it gone. Solomon witnessed the theft — hence “WHERE''S MY ROOT BEER!”"},{"heading":"How to play it","body":"Performatively unbothered. Crack jokes. When the empty bottle surfaces in Phase 3, deny. When the case is found, confess — the room will laugh. You''re not in real trouble."}]', 6);
INSERT OR IGNORE INTO "Character" ("id", "gameId", "personaName", "realName", "role", "loginCode", "isGameMaster", "prop", "avatarColor", "sheet", "sortOrder") VALUES ('cmpg2bw270007ej7d30xh5pkl', 'cmpg2bw0w0000ej7dyc1todr9', 'Eden Hartley', 'Emma', 'SINNER', 'EDEN-07', 0, 'A small flower hair clip or a satin dance ribbon tied around your wrist.', '#c14d8a', '[{"heading":"Who you are","body":"You are 22. Beau''s longtime girlfriend. You teach dance to children. The sweetest person any of these people have met. Your grandparents are your greatest source of love; the Whitfields have adopted you as one of their own."},{"heading":"Your relationship to Richard","body":"Most of the family resented him; you felt sorry for him. Friday he gave you a leather-bound book of his late mother''s poems and said you reminded him of her. Friday night he privately told you he was including your grandparents in his will — $50,000 each. You were moved to tears and told no one, especially not Beau."},{"heading":"Where you were Saturday night","body":"Board games on the bottom floor 8–10. Bonfire 10 onward."},{"heading":"Your secret","body":"Saturday you started to suspect Richard was toying with you. At 9 PM you went to his guest room to verify. You opened the leather portfolio. There was no mention of your grandparents — only a sheet that said “$60M → TURD (final)” in his hand. He had lied to you, using your grandparents to manipulate you. You took the book of poems, left a thank-you note as cover, rearranged a photo frame, and walked out. You''ve known the truth about TURD since 9 PM and told no one."},{"heading":"How to play it","body":"Sweet, loyal, quietly hurt but holding it in. PHASE 3: when the thank-you note is found, confess ONLY the surface — you went to thank him for the book. Do NOT reveal the TURD paper yet. PHASE 4: after Cody shows his photo, step forward: “I saw it too. At nine, in his room. He told me Friday he was leaving something to my grandparents. I went to verify. He had lied to me.”"}]', 7);
INSERT OR IGNORE INTO "Character" ("id", "gameId", "personaName", "realName", "role", "loginCode", "isGameMaster", "prop", "avatarColor", "sheet", "sortOrder") VALUES ('cmpg2bw2d0008ej7ddvafkczx', 'cmpg2bw0w0000ej7dyc1todr9', 'Levi Whitfield', 'Luke', 'SINNER', 'LEVI-08', 0, 'A cheap bucket hat and a single golf glove. AirPods optional.', '#2f8f8c', '[{"heading":"Who you are","body":"You are 18, just graduated, headed to BYU. Bleached hair, thrifted clothes, AirPods in one ear. You play golf and you''re very good. You act uninterested but secretly work hard. You somehow have rich friends with three-tier houseboats."},{"heading":"Your relationship to Richard","body":"Tepid. You found him weird. You were mostly on your phone all weekend."},{"heading":"Where you were Saturday night (official version)","body":"On the porch with Alexander 10 PM–12:30 AM, “looking at the stars.” Alexander has agreed to confirm this."},{"heading":"Your secret","body":"You weren''t on the porch. You were on Wyatt''s family''s three-tier houseboat playing late-night cards (chips, not money — this is important, NOT money) with five rich friends. You snuck out at 10 and back at 12:30. Alexander covered for you without knowing where you went."},{"heading":"What you''re hiding","body":"The boarding ticket from Lake Saunders Houseboat Marina is under your mattress. Your phone has time-stamped photos of you at the houseboat at 11:35 PM — when the murder happened."},{"heading":"How to play it","body":"Performatively bored. When the boarding ticket is found in Phase 3, confess — and keep clarifying chips, not money, three or four times, as a comedic beat. Then realize being off-property looks bad, and show the photos to prove you were elsewhere during the murder."}]', 8);
INSERT OR IGNORE INTO "Character" ("id", "gameId", "personaName", "realName", "role", "loginCode", "isGameMaster", "prop", "avatarColor", "sheet", "sortOrder") VALUES ('cmpg2bw2j0009ej7d3knz0byw', 'cmpg2bw0w0000ej7dyc1todr9', 'Cody Whitfield', 'Ben', 'SINNER', 'CODY-09', 0, 'A small football to toss and a backwards baseball cap. Keep your phone on you the whole game.', '#b5462f', '[{"heading":"Who you are","body":"You are 14. The youngest. Red hair. You play tackle football and love it. You act unbothered like teenagers do (“whatever”). You sometimes feel the family forgets you — you don''t admit this."},{"heading":"Your relationship to Richard","body":"You thought he was funny. He talked to you like an adult at dinner. He told you Friday that you reminded him of himself at your age."},{"heading":"Where you were Saturday night","body":"Bonfire and patio. In bed by 11:30. You missed the murder."},{"heading":"Your secret","body":"Saturday around 2:15 PM you snuck into Richard''s guest room out of curiosity, opened the leather portfolio, and saw a paper that said “$60M → TURD (final)” in his handwriting. You took a photo on your phone. You didn''t know what TURD was. You told no one. (The GM will help you take this photo for real before the game.)"},{"heading":"Your big moment","body":"You are the hero of this game. Quiet-hero. Hold the secret all morning; don''t volunteer anything. In PHASE 4, Alexander will turn to you and ask: “Cody. Anything you''ve been holding onto?” That''s your cue. Pull out the phone. Show the photo. Sebastian is unmasked because of you. Be patient. Be a teenager. When Alexander looks at you, you deliver."}]', 9);
INSERT OR IGNORE INTO "Character" ("id", "gameId", "personaName", "realName", "role", "loginCode", "isGameMaster", "prop", "avatarColor", "sheet", "sortOrder") VALUES ('cmpg2bw2o000aej7db68t8edk', 'cmpg2bw0w0000ej7dyc1todr9', 'Alexander', 'Alex', 'GM', 'GM-ALEX', 1, 'A clipboard with the weekend schedule, a ring of keys, and an “ALEXANDER · HOUSE MANAGER” name tag. Full Clue-butler energy.', '#c9a24b', '[{"heading":"You are the Game Master","body":"You play Alexander, the Whitfields'' lake house manager of four years. You are the omniscient narrator: you hold every clue, walk the family from phase to phase, voice Solomon, fire the auto-reveals, enforce the soft-locks, and guide Cody to the hero turn. You are not a suspect and have no secret."},{"heading":"Use the GM dashboard","body":"Advance the phase to unlock rooms and search permits. Watch the live discovery feed. Fire scripted reveals and Solomon lines into the players'' feed. Open the Phase 4 and Phase 5 ballots and read the tallies. Everything you need is on your dashboard."},{"heading":"Your only line of fiction","body":"In Phase 3, when Levi confesses to sneaking out, confirm: “He asked me to cover for him. I did. I didn''t know where he was actually going. I''m sorry.”"}]', 10);

INSERT OR IGNORE INTO "Clue" ("id", "gameId", "code", "title", "content", "location", "phase", "tag", "token") VALUES ('cmpg2bw2t000bej7dpnoz869a', 'cmpg2bw0w0000ej7dyc1todr9', '2-1', 'A torn corner of paper', 'In Richard''s handwriting: “…told her this afternoon. She took it well, I think. Better than I expected, actually. Maybe I underestimated her.”', 'Living room — taped behind the framed nautical chart of Gig Harbor (cove circled in red).', 2, 'ANNOUNCE', 'NbYSCRORcWU3');
INSERT OR IGNORE INTO "Clue" ("id", "gameId", "code", "title", "content", "location", "phase", "tag", "token") VALUES ('cmpg2bw2x000cej7dze6ikfgf', 'cmpg2bw0w0000ej7dyc1todr9', '2-2', 'A scrap of green tweed', 'A small snip of dark green tweed fabric, torn-edged. Torn from a green tweed jacket.', 'Entryway — inside the inner pocket of Hank''s jacket in the coat closet.', 2, 'KEEP', 'HwjAiC30_3R8');
INSERT OR IGNORE INTO "Clue" ("id", "gameId", "code", "title", "content", "location", "phase", "tag", "token") VALUES ('cmpg2bw32000dej7dlth1wnsb', 'cmpg2bw0w0000ej7dyc1todr9', '2-3', 'Letter from Richard''s attorney', 'A typed fragment on cream paper: “…final draft of the trust beneficiary, as discussed. Per your instructions, this version replaces all prior. I''ll bring the executed copy to the lake house Friday.”', 'Kitchen — behind the cookbooks on the open shelves.', 2, 'KEEP', 'ETDDxC-dNFfV');
INSERT OR IGNORE INTO "Clue" ("id", "gameId", "code", "title", "content", "location", "phase", "tag", "token") VALUES ('cmpg2bw36000eej7d8znmrtql', 'cmpg2bw0w0000ej7dyc1todr9', '2-4', 'Evidence photo: a footprint', 'EVIDENCE PHOTO, Sunday 7:55 AM. A damp footprint on the patio stones, facing the dock. Size: MEN''S 11. Direction: toward the dock. Found by: A.', 'Patio — under the upturned blue kayak.', 2, 'ANNOUNCE', 'tJ6f6tNJjoZJ');
INSERT OR IGNORE INTO "Clue" ("id", "gameId", "code", "title", "content", "location", "phase", "tag", "token") VALUES ('cmpg2bw3a000fej7dhady9rju', 'cmpg2bw0w0000ej7dyc1todr9', '2-5', 'Richard''s “Final List”', 'In Richard''s handwriting, headed “Gig Harbor Visit — Final List”: 1. Hank (crossed out) 2. Catherine (crossed out) 3. Beau (crossed out) 4. Levi (crossed out) 5. Cody (crossed out) 6. [a name, smudged illegible] 7. Eden (crossed out)', 'Living room — folded inside the small plant pot, between soil and liner.', 2, 'KEEP', 'xc1tP5f6iVPe');
INSERT OR IGNORE INTO "Clue" ("id", "gameId", "code", "title", "content", "location", "phase", "tag", "token") VALUES ('cmpg2bw3g000gej7db25noipr', 'cmpg2bw0w0000ej7dyc1todr9', '2-6', 'A grocery receipt', 'Friday receipt, customer R. CROOKSHANK: Solomon''s birdseed $8.49 · Glass-bottle root beer (case) ×2 $43.98 · Tortoise figurine, ceramic $24.00 · Peppermint tea $11.50 · Lobster forks ×3 $36.00. TOTAL: $123.97', 'Kitchen — in the freezer, taped to the bottom of the ice cream tub.', 2, 'KEEP', 'aTi5AatIyE9q');
INSERT OR IGNORE INTO "Clue" ("id", "gameId", "code", "title", "content", "location", "phase", "tag", "token") VALUES ('cmpg2bw3n000hej7dmzm9k68k', 'cmpg2bw0w0000ej7dyc1todr9', '2-7', 'A balled-up cocktail napkin', 'A shopping list scribbled and crossed out: “plane tickets — NYC reservations — tortoise figurine — GONE.”', 'Dining area — taped under the bench with the decorative lanterns.', 2, 'KEEP', '-JCcx3RP6ucF');
INSERT OR IGNORE INTO "Clue" ("id", "gameId", "code", "title", "content", "location", "phase", "tag", "token") VALUES ('cmpg2bw3t000iej7d6ukw66xh', 'cmpg2bw0w0000ej7dyc1todr9', '3-1', 'A burned page of manuscript', 'A partially burned typed page: “…Aunt Catherine had always known the secret about her own mother, but the family pretended. She had decided this would be the year. The book would be her revenge wrapped in a memoir…”', 'Patio — in the bonfire pit, in the cooled ash.', 3, 'ANNOUNCE', 'n2AwClTK7ssz');
INSERT OR IGNORE INTO "Clue" ("id", "gameId", "code", "title", "content", "location", "phase", "tag", "token") VALUES ('cmpg2bw59000rej7dkoh6gjtp', 'cmpg2bw0w0000ej7dyc1todr9', '3-10', 'A handwritten ledger', 'Small, neat handwriting (Sebastian''s). INHERITANCE (est.): Crookshank Inns $11.4M · Bainbridge house $2.1M · Liquid ~$500K = $14M. OWED: MBA loans $312K · NYC apartment $180K · Private placement deposit $750K = $1.24M. “Buffer ratio: 11.6×. Comfortable.”', 'Bottom floor games area — inside a Monopoly box, between the rules booklet and lid.', 3, 'KEEP', 'oKiPsJGesI2P');
INSERT OR IGNORE INTO "Clue" ("id", "gameId", "code", "title", "content", "location", "phase", "tag", "token") VALUES ('cmpg2bw3y000jej7de08fp0uc', 'cmpg2bw0w0000ej7dyc1todr9', '3-2', 'A thank-you note', 'On cream stationery: “Mr. Crookshank — Thank you for the book of your mother''s poems. It meant more than you know. — E.H.”', 'Richard''s guest room — on the desk, under a paperweight.', 3, 'ANNOUNCE', 'FvIAhOdb1Rbn');
INSERT OR IGNORE INTO "Clue" ("id", "gameId", "code", "title", "content", "location", "phase", "tag", "token") VALUES ('cmpg2bw45000kej7d4zq63o47', 'cmpg2bw0w0000ej7dyc1todr9', '3-3', 'Saturday itinerary', 'A typed Saturday itinerary. The 3 PM slot has a handwritten note in Richard''s hand: “3 PM — Pull V aside. Tell her about T. Be gentle. She''ll understand.”', 'Richard''s guest room — inside the leather portfolio (now empty of the envelope).', 3, 'KEEP', 'pLSEb5mD9LGs');
INSERT OR IGNORE INTO "Clue" ("id", "gameId", "code", "title", "content", "location", "phase", "tag", "token") VALUES ('cmpg2bw4b000lej7dt1uoynce', 'cmpg2bw0w0000ej7dyc1todr9', '3-4', 'An opened letter to Vivienne', 'An opened envelope addressed to “Vivienne H.” in Richard''s hand: “My dear Vivi — I read your last note. My answer is no, but let me explain. The theater is wonderful, but it doesn''t pay rent in Manhattan, and I''m not in the business of subsidizing dreams. I love you for asking. — R.”', 'Richard''s guest room — top dresser drawer, under folded socks.', 3, 'KEEP', 'yZsXmElgVkhY');
INSERT OR IGNORE INTO "Clue" ("id", "gameId", "code", "title", "content", "location", "phase", "tag", "token") VALUES ('cmpg2bw4h000mej7dm4iaaucd', 'cmpg2bw0w0000ej7dyc1todr9', '3-5', 'An empty root beer bottle', 'An empty glass-bottle root beer bottle. Label intact. No fingerprints.', 'Patio — in the recycling bin under newspapers.', 3, 'KEEP', 'ZT3q45zab5ue');
INSERT OR IGNORE INTO "Clue" ("id", "gameId", "code", "title", "content", "location", "phase", "tag", "token") VALUES ('cmpg2bw4n000nej7d4bnw7ulq', 'cmpg2bw0w0000ej7dyc1todr9', '3-6', 'A torn guestbook page', 'A torn page from the lake house guestbook: “Saturday — Please let me know what you decide. Your support means the world. The kids in Cambodia need this. — Bella R.”', 'Gazebo — under the cushion of the wicker chair where Solomon''s perch sits.', 3, 'ANNOUNCE', 'cB577UdmqdZ1');
INSERT OR IGNORE INTO "Clue" ("id", "gameId", "code", "title", "content", "location", "phase", "tag", "token") VALUES ('cmpg2bw4t000oej7d24bjdb7q', 'cmpg2bw0w0000ej7dyc1todr9', '3-7', 'A marina boarding ticket', 'A creased boarding ticket: LAKE SAUNDERS HOUSEBOAT MARINA, Slip 14, Saturday Night Card Game. Check-in: 9:48 PM. Guest of: WYATT P.', 'Levi''s bedroom — under the mattress.', 3, 'KEEP', 'qBsDNcTNn16X');
INSERT OR IGNORE INTO "Clue" ("id", "gameId", "code", "title", "content", "location", "phase", "tag", "token") VALUES ('cmpg2bw4z000pej7dl7qjd6np', 'cmpg2bw0w0000ej7dyc1todr9', '3-8', 'A hand-drawn dock diagram', 'A diagram of the dock on graph paper. “11:30 PM” circled at the bonfire; “11:50 PM” written below; between them an arrow toward the dock labeled “~12 min walk.” Someone planned this.', 'Bottom floor — taped behind the orca mural (peel it forward).', 3, 'ANNOUNCE', 'fPkqt9TcBFO3');
INSERT OR IGNORE INTO "Clue" ("id", "gameId", "code", "title", "content", "location", "phase", "tag", "token") VALUES ('cmpg2bw54000qej7d4ybpejbr', 'cmpg2bw0w0000ej7dyc1todr9', '3-9', 'The missing root beer case', 'A case of Richard''s personal root beer, eleven bottles remaining (one missing). Found under the second kayak.', 'Patio — under the second blue kayak.', 3, 'KEEP', 'X4HSBkJDoNwu');
INSERT OR IGNORE INTO "Clue" ("id", "gameId", "code", "title", "content", "location", "phase", "tag", "token") VALUES ('cmpg2bw5f000sej7d90lxq3h9', 'cmpg2bw0w0000ej7dyc1todr9', '4-1', 'The notarized will', 'A heavy cream envelope, notary stamp visible, addressed “Executor — Crookshank Inns Estate.” Inside: “I, Richard Carlton Crookshank, of sound mind and overflowing affection for the slowest creatures on God''s green earth, do hereby leave the entirety of my estate — Crookshank Inns, all twenty-three properties, the Bainbridge house, my liquid assets, and Solomon — to TURD: The Tortoise Urgent Rescue Division, Olympia, Washington. Notarized. — R.C.C.”', 'Dining area — inside the inner pocket of Sebastian''s navy blazer on his breakfast chair.', 4, 'ANNOUNCE', 'f69mZqQfGj4J');
INSERT OR IGNORE INTO "Clue" ("id", "gameId", "code", "title", "content", "location", "phase", "tag", "token") VALUES ('cmpg2bw5k000tej7dgvqimw7z', 'cmpg2bw0w0000ej7dyc1todr9', '4-2', 'A scrap: “11:35 — go”', 'A small scrap of paper torn from a larger sheet, in Vivi''s handwriting: “11:35 — go”', 'Same blazer pocket as 4-1, folded behind the envelope.', 4, 'KEEP', 'sZ8ZNr7ikyxI');
INSERT OR IGNORE INTO "Clue" ("id", "gameId", "code", "title", "content", "location", "phase", "tag", "token") VALUES ('cmpg2bw5o000uej7d4mmfmizj', 'cmpg2bw0w0000ej7dyc1todr9', '4-3', 'Opera binoculars', 'A pair of small black opera-style binoculars. Lens cap off, lens still warm. Found on the balcony loveseat — which has a direct sightline to the dock.', 'Primary suite balcony — propped between the loveseat cushions.', 4, 'ANNOUNCE', 'Gv5o7TOUTKku');
INSERT OR IGNORE INTO "Clue" ("id", "gameId", "code", "title", "content", "location", "phase", "tag", "token") VALUES ('cmpg2bw5t000vej7dzjx9l3z6', 'cmpg2bw0w0000ej7dyc1todr9', '4-4', 'A sticky note', 'A balled-up sticky note, smoothed out, in Vivi''s handwriting: “breathe. it''s done.”', 'Master bathroom of the primary suite — in the trash, under tissues.', 4, 'KEEP', 'xMEMiGwoeWaj');
INSERT OR IGNORE INTO "Clue" ("id", "gameId", "code", "title", "content", "location", "phase", "tag", "token") VALUES ('cmpg2bw5x000wej7dja0t69zz', 'cmpg2bw0w0000ej7dyc1todr9', '4-5', 'The 11:35 bonfire photo', 'EVIDENCE PHOTO, Saturday 11:35 PM. Six people around the bonfire: Hank, Catherine, Vivi, Beau, Eden, Bella. Vivi mid-gesture, telling a story. Note: Sebastian is not in this photograph.', 'Bottom floor — under the rim of the ping pong table, kitchen-side.', 4, 'KEEP', '8g56A31OHXxg');
INSERT OR IGNORE INTO "Clue" ("id", "gameId", "code", "title", "content", "location", "phase", "tag", "token") VALUES ('cmpg2bw63000xej7dx66npbb8', 'cmpg2bw0w0000ej7dyc1todr9', '5-1', 'Vivi''s draft letter', 'A never-sent draft in Vivi''s handwriting: “To whom I am angry with — Then I''ll have to find another way. — V”', 'Vivi''s overnight bag (retrieved in Phase 5 when Hank authorizes the search).', 5, 'ANNOUNCE', '4dNREgsfwIZm');

INSERT OR IGNORE INTO "Announcement" ("id", "gameId", "kind", "title", "body", "phase", "sortOrder", "isScripted", "isReleased") VALUES ('cmpg2bw67000yej7dgbb4qc80', 'cmpg2bw0w0000ej7dyc1todr9', 'AUTO_REVEAL', 'Phase 1 — The body', 'I found Mr. Crookshank in the shallows beside the dock at 7:42 this morning. I''ve called Dr. Langford — he confirms time of death between 11:30 last night and midnight.', 1, 1, 1, 0);
INSERT OR IGNORE INTO "Announcement" ("id", "gameId", "kind", "title", "body", "phase", "sortOrder", "isScripted", "isReleased") VALUES ('cmpg2bw6b000zej7dmz0268q5', 'cmpg2bw0w0000ej7dyc1todr9', 'AUTO_REVEAL', 'Phase 1 — The cleat is missing', 'The brass dock cleat at the end of the dock is missing. The bolts are still in the wood. It looks like someone pulled it free.', 1, 2, 1, 0);
INSERT OR IGNORE INTO "Announcement" ("id", "gameId", "kind", "title", "body", "phase", "sortOrder", "isScripted", "isReleased") VALUES ('cmpg2bw6f0010ej7d6bjebzvv', 'cmpg2bw0w0000ej7dyc1todr9', 'AUTO_REVEAL', 'Phase 1 — The portfolio', 'His leather portfolio was found open in the gazebo. The notarized envelope he''d been carrying all weekend is gone.', 1, 3, 1, 0);
INSERT OR IGNORE INTO "Announcement" ("id", "gameId", "kind", "title", "body", "phase", "sortOrder", "isScripted", "isReleased") VALUES ('cmpg2bw6k0011ej7dnb5megqk', 'cmpg2bw0w0000ej7dyc1todr9', 'AUTO_REVEAL', 'Phase 1 — Solomon', 'Solomon was on his perch in the gazebo. He has been… vocal.', 1, 4, 1, 0);
INSERT OR IGNORE INTO "Announcement" ("id", "gameId", "kind", "title", "body", "phase", "sortOrder", "isScripted", "isReleased") VALUES ('cmpg2bw6o0012ej7ddje51gxy', 'cmpg2bw0w0000ej7dyc1todr9', 'AUTO_REVEAL', 'Phase 2 — The cleat recovered', 'Levi was good enough to dive for it this morning. The cleat was eight feet down, twelve feet off the dock. There''s dried blood on the underside. Dr. Langford is comparing it to the wound.', 2, 5, 1, 0);
INSERT OR IGNORE INTO "Announcement" ("id", "gameId", "kind", "title", "body", "phase", "sortOrder", "isScripted", "isReleased") VALUES ('cmpg2bw6s0013ej7doxqku4w8', 'cmpg2bw0w0000ej7dyc1todr9', 'AUTO_REVEAL', 'Phase 3 — The photo timeline', 'Here are my time-stamped photos from Saturday night. The 11:35 bonfire photo shows six people. Sebastian is not in it. “Sebastian — where were you in this photo?”', 3, 6, 1, 0);
INSERT OR IGNORE INTO "Announcement" ("id", "gameId", "kind", "title", "body", "phase", "sortOrder", "isScripted", "isReleased") VALUES ('cmpg2bw6w0014ej7df2zpg1hh', 'cmpg2bw0w0000ej7dyc1todr9', 'AUTO_REVEAL', 'Phase 4 — The smoke-break receipt', 'Sebastian, you said you stepped out for a smoke at 11:30. I saw you come back in at 11:50. That''s a twenty-minute cigarette.', 4, 7, 1, 0);
INSERT OR IGNORE INTO "Announcement" ("id", "gameId", "kind", "title", "body", "phase", "sortOrder", "isScripted", "isReleased") VALUES ('cmpg2bw700015ej7de7mja36n', 'cmpg2bw0w0000ej7dyc1todr9', 'AUTO_REVEAL', 'Phase 5 — The Christmas story', 'Hank — did Vivi''s bonfire story sound familiar to you? You told me at breakfast you''d heard it before. At Christmas. Word for word. That was a twenty-minute story. Sebastian''s smoke break was twenty minutes long.', 5, 8, 1, 0);
INSERT OR IGNORE INTO "Announcement" ("id", "gameId", "kind", "title", "body", "phase", "sortOrder", "isScripted", "isReleased") VALUES ('cmpg2bw740016ej7dj25yst7e', 'cmpg2bw0w0000ej7dyc1todr9', 'SOLOMON', 'Solomon', 'WHERE''S MY ROOT BEER!', 0, 20, 1, 0);
INSERT OR IGNORE INTO "Announcement" ("id", "gameId", "kind", "title", "body", "phase", "sortOrder", "isScripted", "isReleased") VALUES ('cmpg2bw780017ej7dm442jxq6', 'cmpg2bw0w0000ej7dyc1todr9', 'SOLOMON', 'Solomon (Hank''s gazebo line)', 'Don''t… don''t you talk about her like that…', 2, 21, 1, 0);
INSERT OR IGNORE INTO "Announcement" ("id", "gameId", "kind", "title", "body", "phase", "sortOrder", "isScripted", "isReleased") VALUES ('cmpg2bw7c0018ej7d6i2sgcdb', 'cmpg2bw0w0000ej7dyc1todr9', 'SOLOMON', 'Solomon (rattles Vivi)', 'PRINCESS, PRINCESS, PRINCESS', 3, 22, 1, 0);
INSERT OR IGNORE INTO "Announcement" ("id", "gameId", "kind", "title", "body", "phase", "sortOrder", "isScripted", "isReleased") VALUES ('cmpg2bw7f0019ej7dkwv0eu8g', 'cmpg2bw0w0000ej7dyc1todr9', 'SOLOMON', 'Solomon (after TURD)', 'Sixty MILLION dollars!', 4, 23, 1, 0);
INSERT OR IGNORE INTO "Announcement" ("id", "gameId", "kind", "title", "body", "phase", "sortOrder", "isScripted", "isReleased") VALUES ('cmpg2bw7j001aej7dd413abc1', 'cmpg2bw0w0000ej7dyc1todr9', 'SOLOMON', 'Solomon (TURD)', 'TURD! TURD! TURD!', 4, 24, 1, 0);
INSERT OR IGNORE INTO "Announcement" ("id", "gameId", "kind", "title", "body", "phase", "sortOrder", "isScripted", "isReleased") VALUES ('cmpg2bw7n001bej7dor9ku126', 'cmpg2bw0w0000ej7dyc1todr9', 'SOLOMON', 'Solomon (back at Sebastian)', 'Step outside for some air', 4, 25, 1, 0);
INSERT OR IGNORE INTO "Announcement" ("id", "gameId", "kind", "title", "body", "phase", "sortOrder", "isScripted", "isReleased") VALUES ('cmpg2bw7r001cej7dy7mo9bke', 'cmpg2bw0w0000ej7dyc1todr9', 'SOLOMON', 'Solomon (save for the end)', 'Breathe. It''s done.', 5, 26, 1, 0);

