UPDATE "Clue" SET "title" = 'A torn corner of paper', "content" = 'A torn piece of paper. That''s Richard''s handwriting… and who is “her”?', "location" = 'Living room — taped behind the framed nautical chart of Gig Harbor (cove circled in red).' WHERE "code" = '2-1';
UPDATE "Clue" SET "title" = 'A scrap of green tweed', "content" = 'A scrap of dark green tweed, torn at the edges. Wasn''t Richard wearing a jacket like this?', "location" = 'Entryway — inside the inner pocket of Hank''s jacket in the coat closet.' WHERE "code" = '2-2';
UPDATE "Clue" SET "title" = 'Letter from Richard''s attorney', "content" = 'A letter from Richard''s attorney. He changed the trust — recently. “This version replaces all prior.”', "location" = 'Kitchen — behind the cookbooks on the open shelves.' WHERE "code" = '2-3';
UPDATE "Clue" SET "title" = 'Evidence photo: a footprint', "content" = 'A damp footprint on the patio stones, pointed at the dock. Men''s eleven. Could be anyone''s. Could be.', "location" = 'Patio — under the upturned blue kayak.' WHERE "code" = '2-4';
UPDATE "Clue" SET "title" = 'Richard''s “Final List”', "content" = 'Richard''s “Final List.” Every name struck through but one — and that one''s smudged past reading.', "location" = 'Living room — folded inside the small plant pot, between soil and liner.' WHERE "code" = '2-5';
UPDATE "Clue" SET "title" = 'A grocery receipt', "content" = 'Richard''s grocery run. Birdseed, his root beer, lobster forks… and a tortoise figurine. Why a tortoise?', "location" = 'Kitchen — in the freezer, taped to the bottom of the ice cream tub.' WHERE "code" = '2-6';
UPDATE "Clue" SET "title" = 'A balled-up cocktail napkin', "content" = 'A balled-up napkin. Plane tickets, reservations — all crossed out. “GONE.” Whose writing is this?', "location" = 'Dining area — taped under the bench with the decorative lanterns.' WHERE "code" = '2-7';
UPDATE "Clue" SET "title" = 'A burned page of manuscript', "content" = 'A page that didn''t finish burning. “…her revenge wrapped in a memoir.” Someone wanted this gone.', "location" = 'Patio — in the bonfire pit, in the cooled ash.' WHERE "code" = '3-1';
UPDATE "Clue" SET "title" = 'A handwritten ledger', "content" = 'A ledger in small, careful handwriting. Inheritance weighed against debt. Someone was counting on that money.', "location" = 'Bottom floor games area — inside a Monopoly box, between the rules booklet and lid.' WHERE "code" = '3-10';
UPDATE "Clue" SET "title" = 'A thank-you note', "content" = 'A thank-you note, signed only “E.H.” So Eden was in his room too.', "location" = 'Richard''s guest room — on the desk, under a paperweight.' WHERE "code" = '3-2';
UPDATE "Clue" SET "title" = 'Saturday itinerary', "content" = 'Richard''s itinerary. Penciled into the 3 PM slot: “Pull V aside. Tell her about T.” Tell her what?', "location" = 'Richard''s guest room — inside the leather portfolio (now empty of the envelope).' WHERE "code" = '3-3';
UPDATE "Clue" SET "title" = 'An opened letter to Vivienne', "content" = 'An opened letter to Vivi. “My answer is no.” He''d already turned her down.', "location" = 'Richard''s guest room — top dresser drawer, under folded socks.' WHERE "code" = '3-4';
UPDATE "Clue" SET "title" = 'An empty root beer bottle', "content" = 'An empty root beer bottle, wiped clean. Richard never let anyone near his stash.', "location" = 'Patio — in the recycling bin under newspapers.' WHERE "code" = '3-5';
UPDATE "Clue" SET "title" = 'A torn guestbook page', "content" = 'A torn page from the guestbook. Bella, asking Richard for something. “The kids in Cambodia need this.”', "location" = 'Gazebo — under the cushion of the wicker chair where Solomon''s perch sits.' WHERE "code" = '3-6';
UPDATE "Clue" SET "title" = 'A marina boarding ticket', "content" = 'A boarding ticket. Lake Saunders Marina, checked in 9:48 PM. Someone wasn''t where they said they were.', "location" = 'Levi''s bedroom — under the mattress.' WHERE "code" = '3-7';
UPDATE "Clue" SET "title" = 'A hand-drawn dock diagram', "content" = 'A diagram of the dock. Times marked, an arrow drawn toward the water. This wasn''t a fall. Someone planned it.', "location" = 'Bottom floor — taped behind the orca mural (peel it forward).' WHERE "code" = '3-8';
UPDATE "Clue" SET "title" = 'The missing root beer case', "content" = 'Richard''s missing case of root beer, hidden under a kayak. Eleven bottles left. Who took it?', "location" = 'Patio — under the second blue kayak.' WHERE "code" = '3-9';
UPDATE "Clue" SET "title" = 'The notarized will', "content" = 'A notarized envelope, hidden in a blazer pocket. The will. “I leave the entirety of my estate — Crookshank Inns, every property, the house, all of it — to TURD: the Tortoise Urgent Rescue Division.” Everything. To the tortoises. Not the family.', "location" = 'Dining area — inside the inner pocket of Sebastian''s navy blazer on his breakfast chair.' WHERE "code" = '4-1';
UPDATE "Clue" SET "title" = 'A scrap: “11:35 — go”', "content" = 'A scrap tucked behind the envelope: “11:35 — go.” That''s Vivi''s handwriting.', "location" = 'Same blazer pocket as 4-1, folded behind the envelope.' WHERE "code" = '4-2';
UPDATE "Clue" SET "title" = 'Opera binoculars', "content" = 'Opera binoculars on the balcony loveseat. The lens is still warm. Someone stood up here, watching the dock.', "location" = 'Primary suite balcony — propped between the loveseat cushions.' WHERE "code" = '4-3';
UPDATE "Clue" SET "title" = 'A sticky note', "content" = 'A sticky note, balled up in the trash. Smoothed out, it reads: “breathe. it''s done.” Done… what?', "location" = 'Master bathroom of the primary suite — in the trash, under tissues.' WHERE "code" = '4-4';
UPDATE "Clue" SET "title" = 'The 11:35 bonfire photo', "content" = 'The bonfire photo, stamped 11:35. Everyone''s gathered, mid-laugh. Everyone but Sebastian.', "location" = 'Bottom floor — under the rim of the ping pong table, kitchen-side.' WHERE "code" = '4-5';
UPDATE "Clue" SET "title" = 'Vivi''s draft letter', "content" = 'A letter in Vivi''s hand, never sent. “Then I''ll have to find another way.” …another way.', "location" = 'Vivi''s overnight bag (retrieved in Phase 5 when Hank authorizes the search).' WHERE "code" = '5-1';

UPDATE "Character" SET "personaName" = 'Hank Whitfield', "realName" = 'Daniel', "prop" = 'A bolo tie. Wear it.', "sheet" = '[{"heading":"Who you are","body":"You are 56. Self-made commercial real estate. You grew up on a ranch; your father was a hard man who never gave you a dime. You have a mild temper that flashes when pushed, and a famous “no politics in this house” rule you defend at any provocation. You are the patriarch of the Whitfield family."},{"heading":"Your relationship to Richard","body":"Richard claims to be your 10th step half-brother. You''ve never been able to verify it. He''s been sending letters and bizarre gifts (an engraved lobster fork, a nautical chart of Gig Harbor) for a year. You agreed to host because Catherine wanted to “for the kids.” You don''t trust him and you don''t want his money."},{"heading":"Where you were Saturday night","body":"Bonfire from 9 PM. With Catherine on the patio between 11 and 12. You did NOT go to the dock."},{"heading":"Your secret","body":"At 8 PM in the gazebo, you and Richard had a private confrontation. He mocked your father, the ranch, your “self-made man” story. You shoved him into a stack of life jackets. He laughed. You walked out — and tore a small scrap of fabric from his green tweed jacket as you grabbed him. It''s folded inside the inner pocket of your coat in the entryway closet. Solomon watched the whole thing. You''ve told no one, not even Catherine, because it makes you look guilty."},{"heading":"What you don''t know","body":"Anything about the actual murder."},{"heading":"How to play it","body":"Mortified. You''ll be the loudest voice redirecting suspicion early — that''s your tell, but the family reads it as the temper. When Solomon screeches your gazebo words in Phase 2, you confess. Until then, deny."}]' WHERE "loginCode" = 'HANK-01';
UPDATE "Character" SET "personaName" = 'Catherine Whitfield', "realName" = 'Nicole', "prop" = 'A silk scarf and a small notebook with a pen tucked in the spine.', "sheet" = '[{"heading":"Who you are","body":"You are 51. Loving, traditional, organized to a fault. You write — three published books on naturopathic medicine, herbal remedies, and the spiritual life. Your fourth book has been a secret."},{"heading":"Your relationship to Richard","body":"You found his letters charming at first and convinced Hank to host “for the kids.” You''ve been polite while quietly horrified by his theatrical cruelty."},{"heading":"Where you were Saturday night","body":"Tended the bonfire from 9 PM with brief trips inside. With Hank on the patio between 11 and 12."},{"heading":"Your secret","body":"You''ve been writing a tell-all family memoir for three years — Things My Mother Knew — with uncomfortable truths about every Whitfield. You sent a draft to a publisher in March. Friday you discovered Richard had obtained a copy and hinted at it at dinner. You panicked. At 9:30 PM Saturday you slipped into his guest room, took the draft, and burned every page in the bonfire."},{"heading":"What you''re hiding","body":"Nothing physical — you destroyed it. But a single charred page survived in the cooled fire pit ash."},{"heading":"How to play it","body":"Composed and loving. When the burned page is found in Phase 3, you confess. Frame it as protecting the family, not deceiving them."}]' WHERE "loginCode" = 'CATHERINE-02';
UPDATE "Character" SET "personaName" = 'Vivienne “Vivi” Hawthorne', "realName" = 'Sophia', "prop" = 'Oversized black sunglasses (worn indoors as a Princess bit) and a single theater playbill.', "sheet" = '[{"heading":"PRIVATE — read this alone","body":"This dossier contains the full plan. Do not let anyone see your screen."},{"heading":"Who you are","body":"You are 26. The Princess of the Whitfield family — only daughter, loved by everyone. You live in NYC. Your PR job is glamorous and unfulfilling. You love theater, food, singing, and being adored. You''re married to Sebastian."},{"heading":"Your relationship to Richard","body":"He doted on you — his “Princess.” For a year you''d written him secretly, asking for help to leave PR for theater. Saturday at 3 PM he pulled you aside and told you he was leaving everything to TURD — the Tortoise Urgent Rescue Division. He thought you''d be proud. You smiled. You said you were."},{"heading":"Your secret — you and Sebastian planned the murder together","body":"You walked back to the boathouse, found Sebastian, and told him about TURD. Within two hours you had a plan: he would do it, you would distract. You wrote “11:35 — go” on a note and gave it to him."},{"heading":"The night","body":"Just before 11:30 you slipped to the primary suite balcony with opera binoculars to make sure the dock was empty, then left them on the loveseat (you never came back for them). At 11:30 you launched a Broadway story you''d told before — the same one from last Christmas dinner — to fill exactly the time Sebastian needed. At 11:55 you went upstairs, balled up a sticky note that said “breathe. it''s done.” into the master bathroom trash, and came back at 12:02."},{"heading":"What you must lie about","body":"Whether Richard told you anything Saturday afternoon. Whether you saw anything from upstairs. Whether the “11:35 — go” note is your handwriting. The Christmas story."},{"heading":"How to play it / your break","body":"Charming, devastated, deflective. When Sebastian is unmasked in Phase 4, perform horror — admit nothing. In Phase 5, when the Christmas-story detail surfaces, you have ten seconds. Alexander will guide you. Your final confession is heavy: you are not asking forgiveness, you are explaining."}]' WHERE "loginCode" = 'VIVI-03';
UPDATE "Character" SET "personaName" = 'Sebastian Hawthorne', "realName" = 'Jaymon', "prop" = 'A clip-on tie and a navy blazer (the GM plants the envelope in the inside pocket before guests arrive).', "sheet" = '[{"heading":"PRIVATE — read this alone","body":"This dossier identifies you as the killer. Do not let anyone see your screen."},{"heading":"Who you are","body":"You are 30. Smart, calculating, sarcastic, hard to read. MBA-bound — six figures in loans for an Ivy program in the fall. You want Wall Street. You enjoy strategy games and the taste of certainty."},{"heading":"Your relationship to Richard","body":"Outwardly cordial; privately you saw him as your route into real money. You and Vivi had been quietly drowning in NYC for a year — lease, MBA debt, a private-placement deposit — all sized to an inheritance you assumed was coming."},{"heading":"Where you were Saturday night","body":"“Stepped outside for some air,” 11:30–11:50 PM. A twenty-minute “smoke break.”"},{"heading":"Your secret — you killed him","body":"Saturday afternoon Vivi found you in the boathouse with the news about TURD. You planned together over two hours. At 11:35 you walked to the dock, took the loose cleat, swung once. Richard fell, struck the piling, went into the shallows. You threw the cleat in the lake, took the notarized envelope, and returned to the bonfire at 11:50."},{"heading":"What you''re hiding","body":"The notarized envelope is folded in the inside pocket of your navy blazer (on the back of your breakfast chair — you couldn''t move it). The “11:35 — go” note from Vivi is behind it. Your inheritance-vs-debt ledger is in a Monopoly box on the bottom floor. The dock-layout diagram you drew Friday is taped behind the orca mural."},{"heading":"What you must lie about","body":"The smoke break (you needed air). The envelope (you don''t know where it is). The diagram (never seen it). The ledger (just normal expense tracking)."},{"heading":"How to play it / your break","body":"Cool, dry, slightly above it. Click your pen when nervous — leave that tell in. Smug in Phase 2, uneasy in Phase 3. You break in Phase 4: when Cody''s photo lands, you can deny once, not twice. Confess short and clean. Do NOT implicate Vivi — you take the fall alone."}]' WHERE "loginCode" = 'SEBASTIAN-04';
UPDATE "Character" SET "personaName" = 'Isabelle “Bella” Reyes', "realName" = 'Samantha', "prop" = 'A lanyard with an “International Schools Initiative” badge and a clipboard with non-profit forms.', "sheet" = '[{"heading":"Who you are","body":"You are 25. You work for a humanitarian non-profit that builds schools and teaches English abroad. Sweet, tough, you fight for yourself. You''re engaged to Alexander — but here you''re a guest, not a Whitfield, still working on feeling like one of them."},{"heading":"Your relationship to Richard","body":"He met you at a Whitfield Christmas two years ago and promised your non-profit a $250,000 donation for a Cambodia school. He invited you up this weekend “to lock in the details.”"},{"heading":"Where you were Saturday night","body":"Helping in the kitchen with s''mores and mocktails 9–10:30. Bonfire 10:30 onward."},{"heading":"Your secret","body":"Saturday afternoon you discovered Richard had been stringing you along — the donation was never coming. You confronted him alone in the gazebo at 7 PM. He laughed at you. You walked out fuming."},{"heading":"What you''re hiding","body":"Nothing physical — just the fight. You''re terrified the gazebo confrontation makes you look like the murderer."},{"heading":"How to play it","body":"Tense, defensive, sharper than usual. When the torn guestbook page surfaces in Phase 3, you confess. Frame it as a fight, not a threat."}]' WHERE "loginCode" = 'BELLA-05';
UPDATE "Character" SET "personaName" = 'Beau Whitfield', "realName" = 'Colin', "prop" = 'A gym sweatband headband and a frosted plastic shaker bottle.', "sheet" = '[{"heading":"Who you are","body":"You are 22. The middle child. Fiery red hair. Currently obsessed with the gym (the obsession changes every few months — last year, spoon rings; before that, your never-launched merch line “Beau Thats Hot”). Loud, funny, never a dull moment."},{"heading":"Your relationship to Richard","body":"Friday night you pitched him on investing in a “Beau Thats Hot” relaunch. He laughed in your face — said your idea had “the marketing instincts of a teen with a TikTok addiction.” You smiled and said “respect the honesty.”"},{"heading":"Where you were Saturday night","body":"Bonfire and patio. Tossing a football with Cody and Levi 9–10. You walked off briefly at 10 PM to “use the bathroom.”"},{"heading":"Your secret","body":"At 10 PM, instead of the bathroom, you stole Richard''s entire case of glass-bottle root beer from the kitchen and hid it under the second blue kayak on the patio. You drank one. You wanted to watch his face when he found it gone. Solomon witnessed the theft — hence “WHERE''S MY ROOT BEER!”"},{"heading":"How to play it","body":"Performatively unbothered. Crack jokes. When the empty bottle surfaces in Phase 3, deny. When the case is found, confess — the room will laugh. You''re not in real trouble."}]' WHERE "loginCode" = 'BEAU-06';
UPDATE "Character" SET "personaName" = 'Eden Hartley', "realName" = 'Emma', "prop" = 'A small flower hair clip or a satin dance ribbon tied around your wrist.', "sheet" = '[{"heading":"Who you are","body":"You are 22. Beau''s longtime girlfriend. You teach dance to children. The sweetest person any of these people have met. The Whitfields have taken you in as one of their own."},{"heading":"Your relationship to Richard","body":"Most of the family resented him; you felt sorry for him. Friday he gave you a leather-bound book of his late mother''s poems and said you reminded him of her. Friday night he privately told you he was including your grandparents in his will — $50,000 each. You were moved to tears and told no one, especially not Beau."},{"heading":"Where you were Saturday night","body":"Board games on the bottom floor 8–10. Bonfire 10 onward."},{"heading":"Your secret","body":"Saturday you started to suspect Richard was toying with you. At 9 PM you went to his guest room to verify. You opened the leather portfolio. There was no mention of your grandparents — only a sheet that said “$60M → TURD (final)” in his hand. He had lied to you, using your grandparents to manipulate you. You took the book of poems, left a thank-you note as cover, rearranged a photo frame, and walked out. You''ve known the truth about TURD since 9 PM and told no one."},{"heading":"How to play it","body":"Sweet, loyal, quietly hurt but holding it in. PHASE 3: when the thank-you note is found, confess ONLY the surface — you went to thank him for the book. Do NOT reveal the TURD paper yet. PHASE 4: after Cody shows his photo, step forward: “I saw it too. At nine, in his room. He told me Friday he was leaving something to my grandparents. I went to verify. He had lied to me.”"}]' WHERE "loginCode" = 'EDEN-07';
UPDATE "Character" SET "personaName" = 'Levi Whitfield', "realName" = 'Luke', "prop" = 'A cheap bucket hat and a single golf glove. AirPods optional.', "sheet" = '[{"heading":"Who you are","body":"You are 18, just graduated, headed to BYU. Bleached hair, thrifted clothes, AirPods in one ear. You play golf and you''re very good. You act uninterested but secretly work hard. You somehow have rich friends with three-tier houseboats."},{"heading":"Your relationship to Richard","body":"Tepid. You found him weird. You were mostly on your phone all weekend."},{"heading":"Where you were Saturday night (official version)","body":"On the porch with Alexander 10 PM–12:30 AM, “looking at the stars.” Alexander has agreed to confirm this."},{"heading":"Your secret","body":"You weren''t on the porch. You were on Wyatt''s family''s three-tier houseboat playing late-night cards (chips, not money — this is important, NOT money) with five rich friends. You snuck out at 10 and back at 12:30. Alexander covered for you without knowing where you went."},{"heading":"What you''re hiding","body":"The boarding ticket from Lake Saunders Houseboat Marina is under your mattress. Your phone has time-stamped photos of you at the houseboat at 11:35 PM — when the murder happened."},{"heading":"How to play it","body":"Performatively bored. When the boarding ticket is found in Phase 3, confess — and keep clarifying chips, not money, three or four times, as a comedic beat. Then realize being off-property looks bad, and show the photos to prove you were elsewhere during the murder."}]' WHERE "loginCode" = 'LEVI-08';
UPDATE "Character" SET "personaName" = 'Cody Whitfield', "realName" = 'Ben', "prop" = 'A small football to toss and a backwards baseball cap. Keep your phone on you the whole game.', "sheet" = '[{"heading":"Who you are","body":"You are 14. The youngest. Red hair. You play tackle football and love it. You act unbothered like teenagers do (“whatever”). You sometimes feel the family forgets you — you don''t admit this."},{"heading":"Your relationship to Richard","body":"You thought he was funny. He talked to you like an adult at dinner. He told you Friday that you reminded him of himself at your age."},{"heading":"Where you were Saturday night","body":"Bonfire and patio. In bed by 11:30. You missed the murder."},{"heading":"Your secret","body":"Saturday around 2:15 PM you snuck into Richard''s guest room out of curiosity, opened the leather portfolio, and saw a paper that said “$60M → TURD (final)” in his handwriting. You took a photo on your phone. You didn''t know what TURD was. You told no one. (The GM will help you take this photo for real before the game.)"},{"heading":"Your big moment","body":"You are the hero of this game. Quiet-hero. Hold the secret all morning; don''t volunteer anything. In PHASE 4, Alexander will turn to you and ask: “Cody. Anything you''ve been holding onto?” That''s your cue. Pull out the phone. Show the photo. Sebastian is unmasked because of you. Be patient. Be a teenager. When Alexander looks at you, you deliver."}]' WHERE "loginCode" = 'CODY-09';
UPDATE "Character" SET "personaName" = 'Alexander', "realName" = 'Alex', "prop" = 'A clipboard with the weekend schedule, a ring of keys, and an “ALEXANDER · HOUSE MANAGER” name tag. Full Clue-butler energy.', "sheet" = '[{"heading":"You are the Game Master","body":"You play Alexander, the Whitfields'' lake house manager of four years. You are the omniscient narrator: you hold every clue, walk the family from phase to phase, voice Solomon, fire the auto-reveals, enforce the soft-locks, and guide Cody to the hero turn. You are not a suspect and have no secret."},{"heading":"Use the GM dashboard","body":"Advance the phase to unlock rooms and search permits. Watch the live discovery feed. Fire scripted reveals and Solomon lines into the players'' feed. Open the Phase 4 and Phase 5 ballots and read the tallies. Everything you need is on your dashboard."},{"heading":"Your only line of fiction","body":"In Phase 3, when Levi confesses to sneaking out, confirm: “He asked me to cover for him. I did. I didn''t know where he was actually going. I''m sorry.”"}]' WHERE "loginCode" = 'GM-ALEX';
